SELECT id, display_name, allowed_scopes, client_status, created_at, revoked_at
FROM iam_oauth_clients
WHERE id = #{clientId}

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM iam_oauth_client_secrets
    WHERE client_id = #{clientId}
      AND revoked_at IS NULL
      AND valid_until > #{at}
) THEN 1 ELSE 0 END

mapper.update:
UPDATE iam_oauth_client_secrets
SET valid_until = #{validUntil}
WHERE client_id = #{clientId} AND revoked_at IS NULL AND valid_until IS NULL

UPDATE iam_oauth_clients
SET client_status = 'REVOKED', revoked_at = #{revokedAt}
WHERE id = #{clientId} AND client_status = 'ACTIVE'

UPDATE iam_oauth_client_secrets
SET revoked_at = #{revokedAt}
WHERE client_id = #{clientId} AND revoked_at IS NULL
